// 坐标与计量单位
// 全工程只有一种长度单位：1 单位 = 10 米（显示时乘 10 变成"约 XX 米"）。
// x/z 是水平面（校园平面图），y 是高度（向上为正）。
// 地形高度另存在 heightMap 里，由 getHeight()/getHeightSmooth() 双线性查表；
// 所以"贴地"不是 y=0，而是 y = getHeight(x,z)。
typedef struct { double x, y, z; } Vec3D;

// 哈希表节点（id → 顶点下标）
// 为什么需要它：邻接表的每条边只存目标顶点的 id（int），而松弛/遍历时要拿到
// 它在 vertices[] 里的下标。没有哈希就得线性扫 999 个槽位 —— Dijkstra 内层
// 是 O(E) 次查找，会从 842 次哈希命中退化成 84 万次比较。
// 冲突用链地址法（next 单链），桶数取 2 × MAX_STATIONS = 1998，
// 实测装载因子 ≈ 0.34、平均链长 < 1.4。
typedef struct HashNode {
    int id;
    int vidx;
    char name[MAX_NAME];
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode* buckets[MAX_STATIONS * 2];
    int count;
} HashTable;

// 邻接表的边节点
// 图是**无向图**：一条边会在两个顶点的链表里各存一份（addEdge 负责双向插入），
// 所以数边时要按"有向条目 / 2"折半。
// weight 是整数（= ⌈几何长度 × 通行系数⌉），用 int 而不是 float：
// 避免浮点累加误差，也让 Dijkstra/Floyd 的比较与相等判断是精确的。
// 边权上限 MAX_EDGE_WEIGHT（1e6），保证 int 累加不溢出。
typedef struct Edge {
    int to;
    int weight;
    struct Edge* next;
} Edge;

// 顶点：站点与路口共用一个数组
// id 的符号就是类型标记：> 0 = 建筑站点（1..76），< 0 = 道路口（-1..-601）。
// 这样"是不是路口"只要判 id < 0，不需要额外字段，也天然避免两类 id 冲突。
// active 是**惰性删除**：删除只置 0，不前移数组 —— 因为边里存的是 id 不是下标，
// 前移会让所有 Edge.to 失效。查找时由 findVertexIndex 的 active 检查自然屏蔽。
typedef struct Vertex {
    int id;
    char name[MAX_NAME];
    Vec3D pos;
    float color[3];
    float w, h, d;
    Edge* head;
    int active;
} Vertex;

// 图对象：定长数组 + 哈希索引 + 一把锁
// vertices 是**定长槽位池**（MAX_STATIONS = 999），不是链表：校园规模下
// 分配/释放的复杂度不值得，定长数组还能按 id 直接算槽位概率最高。
// vertexCount 只统计 active 的数量。
// cs 是 Win32 临界区：控制台线程（菜单 7~11 等）与 GL 线程（鼠标点选）都会读图，
// 所有会改图的操作都必须 EnterCriticalSection 包住。
typedef struct {
    Vertex vertices[MAX_STATIONS];
    int vertexCount;
    HashTable* hash;
    CRITICAL_SECTION cs;
} Graph;

// 几何层 · 建筑
// pos 是**中心点**（世界坐标），shape[] 存的是**相对中心的轮廓偏移**。
// 这个拆分是为了拖动：移动一栋楼只改 pos，几十个轮廓顶点一个都不用动；
// 代价是求世界坐标时要 pos + shape[i]（拾取时做一次）。
// minX..maxZ 是由 shape 预计算出的**局部包围盒**，供 rayAABB 快速剔除；
// 改形状后必须调 computeBoundingBoxes() 重算，否则点选会错位。
typedef struct {
    char name[MAX_NAME];
    Vec3D pos;
    Vec3D shape[MAX_BUILDING_VERTS];
    int vertexCount;
    float height;
    float color[3];
    float minX, maxX, minZ, maxZ;
} RealBuilding;

// 几何层 · 道路 = 变长折线
// wx/wz 是等长并行数组（第 i 个点的 x 与 z），pointCount 是有效长度；
// 不用点结构体数组是为了少一层间接、缓存更友好。
// kind 区分细路/粗路（只影响绘制宽度），coef 是通行系数：
// 边权 = ⌈几何长度 × coef⌉，coef <= 0 表示封路（建图时直接跳过，不产生边）。
// 删除单条道路用**前移覆盖**（后续元素整体左移），O(n) 但 n ≤ 999 且是人工低频操作；
// 副作用是"任何缓存了道路下标的模式"必须在删除前退出。
typedef struct {
    int pointCount;
    float wx[MAX_PATH_POINTS], wz[MAX_PATH_POINTS];
    unsigned char kind;
    float coef;
} RoadPath;

