#define PAN_LIMIT 150.0f

// 功能：按缩放倍数重算 UI 逻辑宽高
// 原理：uiW = 窗口宽 / uiScale；缩放夹在 [0.6, 3.0]
static void uiSync(void) {
    if (uiScale < 0.6f) uiScale = 0.6f;
    if (uiScale > 3.0f) uiScale = 3.0f;
    uiW = (float)winW / uiScale;
    uiH = (float)winH / uiScale;
}


// 功能：界面坐标：逻辑像素与窗口像素的换算
// 实现：按参数完成一次具体操作
static int uiPx(int px) {
    int v = (int)((float)px * uiScale + 0.5f);
    return (v < 6) ? 6 : v;
}


// 功能：窗口坐标 → UI 逻辑坐标（并把 y 翻转成向上）
// 原理：lx = mx/uiScale，ly = uiH - my/uiScale；绘制与命中都调它，保证坐标同源
static void uiMouse(int mx, int my, float* lx, float* ly) {
    *lx = (float)mx / uiScale;
    *ly = uiH - (float)my / uiScale;
}



// 功能：界面坐标：逻辑像素与窗口像素的换算
// 实现：按参数完成一次具体操作
static void uiScaleStep(float d) {
    uiScale += d;
    uiSync();
    printf("[界面] UI 缩放 = %.2fx（逻辑尺寸 %d x %d）\n",
           uiScale, (int)uiW, (int)uiH);
    glutPostRedisplay();
}

