#define MAX_MANUAL_EDGES 64
static int manualU[MAX_MANUAL_EDGES];
static int manualV[MAX_MANUAL_EDGES];
static int manualN = 0;


// 功能：辅助函数：manualEdgeAdd
// 实现：含循环遍历
static int manualEdgeAdd(int u, int v) {
    int i;
    if (u == v) return 0;
    for (i = 0; i < manualN; i++)
        if ((manualU[i] == u && manualV[i] == v) ||
            (manualU[i] == v && manualV[i] == u)) return 1;
    if (manualN >= MAX_MANUAL_EDGES) return 0;
    manualU[manualN] = u;
    manualV[manualN] = v;
    manualN++;
    return 1;
}


// 功能：辅助函数：manualEdgeRemove
// 实现：含循环遍历
static void manualEdgeRemove(int u, int v) {
    int k, w = 0;
    for (k = 0; k < manualN; k++) {
        if ((manualU[k] == u && manualV[k] == v) ||
            (manualU[k] == v && manualV[k] == u)) continue;
        manualU[w] = manualU[k];
        manualV[w] = manualV[k];
        w++;
    }
    manualN = w;
}
