// 撤销快照：整份几何的深拷贝
// 存的是"操作前的状态"，不是操作本身（不是命令模式）。
// 为什么：几何是可变长折线，"逆操作"要写十几种且容易漏；
// 76 栋 + 268 条路的整份拷贝只有几十 KB，用空间换正确性。
// 一个快照必须同时包含建筑表、道路表与环路，缺一个就会出现"撤销后图裂开"。
typedef struct {
    int buildingCount;
    RealBuilding buildings[MAX_BUILDINGS];
    int roadCount;
    RoadPath roads[MAX_ROADS];
    RoadPath ring;
} UndoSnapshot;

// 撤销栈：LIFO，固定容量 8
// push 时若已满，把 [0] 丢弃、整体左移一格（memmove），再写栈顶 ——
// 即"只保留最近 8 步"，不扩容（快照较大，动态扩容会让峰值内存不可控）。
// 连续同类操作要合并：调高度用 heightEditIdx 记住对象，同一栋只压一次；
// 无实际改动的快照（按下未拖动）要在松手时弹掉，否则点几下就把栈占满。
static UndoSnapshot undoStack[MAX_UNDO];
static int undoTop = 0;


